\documentclass[11pt]{article}
\usepackage{amsmath,amssymb}

\newcommand{\vect}[1]{\mathf{#1}}
\newcommand{\dd}{\mathrm{d}}

\title{Problem Set: Static Electric and Magnetic Fields}
\author{Course notes --- T.~Aldridge}
\date{April 2026}

\begin{document}
\maketitle

\section{Warm-up}
Let $\vect{E}$ be the electrostatic field of a point charge
located at the origin, and let $\vect{r}$ denote the field point.
The field falls off with the inverse square of $|\vect{r}|$,
and its curl vanishes in the whole region away from the charge.

\section{Magnetic Induction}
A steady line current produces an induction $\vect{B}$ whose
field lines close around the conductor.
The circulation of $\vect{B}$ around any loop threading the
conductor is fixed by the enclosed current,
independent of the shape of the loop.

\section{Vector Identities}
For any smooth field $\vect{F}$ the identity
$\nabla \times (\nabla \times \vect{F})
= \nabla (\nabla \cdot \vect{F}) - \nabla^2 \vect{F}$
reduces many computations to the scalar potential.
Use it to show that the induction above can be written through
a vector potential whose divergence vanishes.

\section{Discussion}
The two static problems share the same formal structure:
one field is irrotational, the other is solenoidal,
and both are fixed once the sources and the boundary
conditions are specified.
\end{document}

